import React, { createContext, useContext, useState, useEffect } from 'react';
import * as SecureStore from 'expo-secure-store';
import { LightTheme, DarkTheme, MidnightTheme, EmeraldTheme, CharcoalTheme, SlateTheme, CocoaTheme } from '@/constants/theme';

type Theme = 'light' | 'dark' | 'midnight' | 'emerald' | 'charcoal' | 'slate' | 'cocoa';
type Language = 'en' | 'am' | 'om' | 'ti';
type CalendarType = 'ethiopian' | 'gregorian';
type TimeSystem = 'device' | 'ethiopian';

interface UserProfile {
  name: string;
  businessName: string;
  avatarIndex: number;
  avatarUri?: string;
}

interface NotificationSettings {
  stock: boolean;
  expiration: boolean;
  daily: boolean;
  credit: boolean;
  debt: boolean;
}

export const PROFILE_IMAGES = [
  require('../assets/images/profile/profile1.png'),
  require('../assets/images/profile/profile2.png'),
  require('../assets/images/profile/profile3.png'),
  require('../assets/images/profile/profile4.png'),
  require('../assets/images/profile/profile5.png'),
  require('../assets/images/profile/profile6.png'),
  require('../assets/images/profile/profile7.png'),
  require('../assets/images/profile/profile8.png'),
  require('../assets/images/profile/profile9.png'),
  require('../assets/images/profile/profile10.png'),
];

interface SettingsContextType {
  theme: Theme;
  language: Language;
  calendarType: CalendarType;
  timeSystem: TimeSystem;
  userProfile: UserProfile;
  notifications: NotificationSettings;
  pin: string | null;
  setTheme: (theme: Theme) => void;
  setLanguage: (lang: Language) => void;
  setCalendarType: (type: CalendarType) => void;
  setTimeSystem: (system: TimeSystem) => void;
  setUserProfile: (profile: UserProfile) => void;
  setNotifications: (settings: NotificationSettings) => void;
  setPin: (pin: string | null) => void;
  t: (key: string, params?: Record<string, string>) => string;
  colors: typeof LightTheme;
}

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

